(116,'77976151-dd28-4f64-b11e-22452d7372e7','assistant','**PHP – Campus Repository (uses table name `campus`)**\n\n```php\n<?php\nnamespace App\\Repository;\n\nuse mysqli;\n\nclass CampusRepository\n{\n    /** @var mysqli */\n    private $db;\n\n    public function __construct(mysqli $db)\n    {\n        $this->db = $db;\n    }\n\n    // Fetch a single campus\n    public function findById(int $id): ?array\n    {\n        $stmt = $this->db->prepare(\n            \'SELECT id, code, description, added_by, created_at\n             FROM campus\n             WHERE id = ?\'\n        );\n        $stmt->bind_param(\'i\', $id);\n        $stmt->execute();\n        $result = $stmt->get_result();\n        $row    = $result->fetch_assoc();\n\n        $stmt->close();\n        return $row ?: null;\n    }\n\n    // List all campuses (id asc)\n    public function all(): array\n    {\n        $res = $this->db->query(\'SELECT id, code, description FROM campus ORDER BY id\');\n        return $res->fetch_all(MYSQLI_ASSOC);\n    }\n\n    // Create or update campus\n    public function upsert(string $code, string $description, ?int $id = null): bool\n    {\n        if ($id) {\n            $stmt = $this->db->prepare(\n                \'UPDATE campus SET code = ?, description = ?\n                 WHERE id = ?\'\n            );\n            $stmt->bind_param(\'ssi\', $code, $description, $id);\n        } else {\n            $stmt = $this->db->prepare(\n                \'INSERT INTO campus (code, description) VALUES (?, ?)\'\n            );\n            $stmt->bind_param(\'ss\', $code, $description);\n        }\n\n        $ok = $stmt->execute();\n        $stmt->close();\n        return $ok;\n    }\n\n    // Delete campus\n    public function delete(int $id): bool\n    {\n        $stmt = $this->db->prepare(\'DELETE FROM campus WHERE id = ?\');\n        $stmt->bind_param(\'i\', $id);\n        $ok = $stmt->execute();\n        $stmt->close();\n        return $ok;\n    }\n}\n```\n\n---\n\n**JavaScript – Modern fetch‑based form submit**\n\n```js\n// idempotent form submit – uses vanilla JS, no jQuery\ndocument.addEventListener(\'DOMContentLoaded\', () => {\n  const form = document.getElementById(\'campus-form\');\n  if (!form) return;\n\n  form.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n\n    const data = new FormData(form);\n    const url = form.action || \'api/campus\'; // API endpoint\n\n    try {\n      const res = await fetch(url, {\n        method: \'POST\',\n        body: data,\n        // fetch automatically sets correct headers for FormData\n      });\n\n      const json = await res.json();\n\n      if (json.status === \'success\') {\n        alert(\'Campus saved successfully.\');\n        // close modal, reload table, etc.\n      } else {\n        alert(`Error: ${json.message}`);\n      }\n    } catch (err) {\n      console.error(err);\n      alert(\'Something went wrong. Please try again.\');\n    }\n  });\n});\n```\n\nThese snippets show the concise, clean style I follow: meaningful names, prepared statements (PHP) for safety, minimal but clear comments, no framework boilerplate, and modern ES‑6+ JavaScript for browser interactions.','2026-10-15 14:48:24'),
