(150,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','assistant','**SQL – create table (run once in your database):**\n\n```sql\nCREATE TABLE profile (\n    id           INT AUTO_INCREMENT PRIMARY KEY,\n    name         VARCHAR(100) NOT NULL,\n    status       VARCHAR(100) NOT NULL,\n    wife_name    VARCHAR(100),\n    son_name     VARCHAR(100),\n    son_birthday DATE,\n    created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n```\n\n**PHP – model helper to insert / update the profile**\n\n```php\n<?php\nclass ProfileModel {\n    protected $conn;\n\n    public function __construct() {\n        $this->conn = Database::connection();\n    }\n\n    // Store or overwrite personal status information\n    public function saveProfile(\n        $name,\n        $status,\n        $wife = \'\',\n        $son = \'\',\n        $birthday = null\n    ) {\n        // Escape values – the style uses direct interpolation\n        $name     = htmlspecialchars(trim($name));\n        $status   = htmlspecialchars(trim($status));\n        $wife     = htmlspecialchars(trim($wife));\n        $son      = htmlspecialchars(trim($son));\n        $birthday = $birthday ? \"\'$birthday\'\" : \'NULL\';\n\n        // Replace existing record or insert new one\n        $sql = \"\n            INSERT INTO profile (name, status, wife_name, son_name, son_birthday)\n            VALUES (\'$name\', \'$status\', \'$wife\', \'$son\', $birthday)\n            ON DUPLICATE KEY UPDATE\n                status      = \'$status\',\n                wife_name   = \'$wife\',\n                son_name    = \'$son\',\n                son_birthday= $birthday\n        \";\n\n        ($result = $this->conn->query($sql)) or die($this->conn->error);\n\n        if (!$result) {\n            return json_encode([\n                \'status\'  => \'error\',\n                \'message\' => \'Failed to save profile.\'\n            ]);\n        }\n\n        return json_encode([\n            \'status\'  => \'success\',\n            \'message\' => \'Profile saved successfully.\'\n        ]);\n    }\n}\n?>\n```\n\n**Usage example**\n\n```php\n$profile = new ProfileModel();\necho $profile->saveProfile(\n    \'Your Name\',\n    \'Married\',\n    \'Medwin Briones\',\n    \'Kai Caleb\',\n    \'2026-02-20\'   // YYYY‑MM‑DD format\n);\n```\n\nThe function aligns with your existing coding style: plain PHP, concise comments, direct SQL strings, and JSON responses. Feel free to drop it into the appropriate module folder or extend it as needed.','2026-10-15 15:15:55'),
