(1,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','campus_details.php','<?php\r\n\r\nsession_start();\r\ninclude_once \'../../app/classes/Database.class.php\';\r\ninclude_once \'../../app/classes/Page.class.php\';\r\ninclude_once \'../../app/classes/models/Extras.php\';\r\ninclude_once Extras::fileExists(\"app/classes/models/CampusModel.php\");\r\ninclude_once Extras::fileExists(\"app/classes/controllers/CampusController.class.php\"); \r\nif (isset($_GET[\'id\'])) {\r\n    $CampusModel = new CampusModel();\r\n    $campus = $CampusModel->getCampusDetails($_GET[\'id\']); \r\n} ?>\r\n\r\n<?php $isEdit = !empty($campus[\'id\']); ?>\r\n<div tag=\"display\" class=\"modal-form\">\r\n    <form id=\"campus-form\" enctype=\"multipart/form-data\">\r\n        <input type=\"hidden\" name=\"id\" id=\"id\" value=\"<?=$campus[\'id\'] ?? \'\'?>\">\r\n        <section class=\"form-section\">\r\n            <div class=\"form-group\">\r\n                <label for=\"code\">Code</label>\r\n                <input type=\"text\" class=\"form-control\" name=\"code\" id=\"code\" value=\"<?=$campus[\'code\'] ?? \'\'?>\" required>\r\n            </div>\r\n            <div class=\"form-group\">\r\n                <label for=\"description\">Campus name</label>\r\n                <input type=\"text\" class=\"form-control\" name=\"description\" id=\"description\" value=\"<?=$campus[\'description\'] ?? \'\'?>\" required>\r\n            </div>\r\n        </section>\r\n\r\n        <div class=\"modal-form-footer\">\r\n            <button type=\"button\" class=\"btn btn-secondary\" data-dismiss=\"modal\">Cancel</button>\r\n            <button type=\"submit\" class=\"btn btn-primary\"><i class=\"fas fa-save\" aria-hidden=\"true\"></i> <?= $isEdit ? \'Save changes\' : \'Add campus\' ?></button>\r\n        </div>\r\n    </form>\r\n</div>\r\n\r\n<script>\r\n    $(function() {\r\n        $(document).off(\'submit\', \'#campus-form\').on(\'submit\', \'#campus-form\', async function(e) {\r\n            e.preventDefault();\r\n            var formData = new FormData(this);\r\n            if (!(await opsConfirm({ title: $(this).find(\'[name=id]\').val() ? \'Save changes to this campus?\' : \'Add this campus?\', message: $(this).find(\'[name=id]\').val() ? \'The campus will be updated with the details you entered.\' : \'A new campus will be created with the details you entered.\', confirmText: $(this).find(\'[name=id]\').val() ? \'Save changes\' : \'Add campus\' }))) return;\r\n            $.ajax({\r\n                url: \'<?=Extras::fileExists(\"app/classes/controllers/CampusController.class.php\");?>?action=saveTransaction\',\r\n                type: \'POST\',\r\n                data: formData,\r\n                contentType: false,\r\n                processData: false,\r\n                success: function(response) {\r\n                    var res = JSON.parse(response);\r\n                    if (res.status === \'success\') {\r\n                        toastr.success(res.message);\r\n                        $(\'#campus-modal\').modal(\'hide\');\r\n                        $(\'#table-campus\').DataTable().ajax.reload();\r\n                    } else {\r\n                        toastr.error(res.message);\r\n                    }\r\n                },\r\n                error: function() {\r\n                    toastr.error(\'Something went wrong. Please try again.\');\r\n                }\r\n            });\r\n        });\r\n    });\r\n</script>','2026-10-15 14:38:04'),
(2,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','CampusController.class.php','<?php\r\nif (session_status() === PHP_SESSION_NONE) {\r\n    session_start();\r\n}\r\nif (!function_exists(\'fileExists\')) {\r\n    function fileExists($file=\"\") {\r\n        for ($i=0; $i<10 && !file_exists($file); $i++) {\r\n            $file = \"../\" . $file;\r\n        } return $file;\r\n    }\r\n}\r\n\r\ninclude_once fileExists(\'app/classes/models/CampusModel.php\');\r\n\r\nclass CampusController extends CampusModel {\r\n    \r\n    protected $conn;\r\n    protected $user;\r\n\r\n    public function __construct() {\r\n        parent::__construct();\r\n    }\r\n\r\n    public function initSaveTransaction($post, $files) {\r\n        $id = htmlspecialchars(trim($post[\'id\'] ?? \'\'));\r\n        $code = htmlspecialchars(trim($post[\'code\'] ?? \'\'));\r\n        $description = htmlspecialchars(trim($post[\'description\']));\r\n\r\n        $existing = $this->checkCampusCode($id, $code);\r\n        if ($existing) {\r\n            return json_encode([\'status\' => \'error\', \'message\' => \'Campus Code already taken.\']);\r\n        }\r\n\r\n        $result = $this->saveTransaction($id, $this->user, $code, $description);\r\n        $action = $id ? \'Updated\' : \'Added\';\r\n        $this->insertAuditTrail(\'Campus\', $code, \"$action campus information\", $this->user);\r\n        return $result;\r\n    }\r\n\r\n    public function initDeleteCampus($post, $files) {\r\n        $id = htmlspecialchars(trim($post[\'id\'] ?? \'\'));\r\n        $result = $this->deleteCampus($id);\r\n        $code = $this->getSingleTableData(\'inventory_campus\', $id, \'code\');\r\n        $this->insertAuditTrail(\'Campus\', $code, \'Deleted campus\', $this->user);\r\n        return $result;\r\n    }\r\n}\r\n\r\nif (isset($_GET[\'action\'])) {\r\n    $action = $_GET[\'action\'];\r\n    $campus = new CampusController();\r\n    if ($action == \'saveTransaction\') {\r\n        echo $campus->initSaveTransaction($_POST, $_FILES);\r\n        exit;\r\n    }\r\n    if ($action == \'deleteCampus\') {\r\n        echo $campus->initDeleteCampus($_POST, $_FILES);\r\n        exit;\r\n    }\r\n}','2026-10-15 14:38:04'),
(3,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','CampusModel.php','<?php\r\nif (!function_exists(\'fileExists\')) {\r\n    function fileExists($file=\"\") {\r\n        for ($i=0; $i<10 && !file_exists($file); $i++) {\r\n            $file = \"../\" . $file;\r\n        } return $file;\r\n    }\r\n}\r\n\r\ninclude_once fileExists(\'app/classes/models/Extras.php\');\r\n\r\nclass CampusModel extends Extras {\r\n    protected $conn;\r\n    protected $user;\r\n\r\n    public function __construct() {\r\n        parent::__construct();\r\n    }\r\n\r\n    public function getCampusDetails($id=\'\') {\r\n        $sql = \"SELECT * FROM inventory_campus WHERE id = \'$id\'\";\r\n        ($data = $this->conn->query($sql)) or die($this->conn->error);\r\n        return $data->num_rows > 0 ? $data->fetch_assoc() : [];\r\n    }\r\n\r\n    public function saveTransaction($id=\'\', $user=\'\', $code=\'\', $description=\'\') {\r\n        if ($id == \'\') {\r\n            $sql = \"INSERT INTO inventory_campus (code, description, added_by) VALUES (\'$code\', \'$description\', \'$user\')\";\r\n        } else {\r\n            $sql = \"UPDATE inventory_campus SET code = \'$code\', description = \'$description\', added_by = \'$user\' WHERE id = $id\";\r\n        }\r\n        ($data = $this->conn->query($sql)) or die($this->conn->error);\r\n        if (!$data) return json_encode([\'status\' => \'error\', \'message\' => \'Failed to save campus.\']);\r\n        \r\n        return json_encode([\'status\' => \'success\', \'message\' => \'Campus saved successfully.\']);\r\n    }\r\n\r\n    public function deleteCampus($id=\'\') {\r\n        $sql = \"DELETE FROM inventory_campus WHERE id = $id\";\r\n        ($data = $this->conn->query($sql)) or die($this->conn->error);\r\n        if (!$data) return json_encode([\'status\' => \'error\', \'message\' => \'Failed to delete campus.\']);\r\n        \r\n        return json_encode([\'status\' => \'success\', \'message\' => \'Campus deleted successfully.\']);\r\n    }\r\n\r\n    public function checkCampusCode($id=\'\', $code=\'\') {\r\n        $where = $id != \'\' ? \" AND id != \'$id\' \" : \"\";\r\n        $sql = \"SELECT id FROM inventory_campus WHERE code = \'$code\' $where\";\r\n        ($data = $this->conn->query($sql)) or die($this->conn->error);\r\n        return $data->num_rows > 0;\r\n    }\r\n}\r\n','2026-10-15 14:38:04'),
(4,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','Database.class.php','<?php\r\n\r\nclass Database {\r\n    private static $host = \'localhost\';\r\n    private static $dbname = \'inventory_main\';\r\n    private static $user = \'root\';\r\n    private static $pass = \'\';\r\n    \r\n    // private static $host = \'localhost\';\r\n    // private static $dbname = \'scvigrcx_inventory\';\r\n    // private static $user = \'scvigrcx_mainuser\';\r\n    // private static $pass = \'C+RsLEOaCP83\';\r\n\r\n    public static function connection() {\r\n        try {\r\n            date_default_timezone_set(\'Asia/Manila\');\r\n            $conn = new mysqli(self::$host, self::$user, self::$pass, self::$dbname);\r\n            return $conn;\r\n        } catch (Exception $e) {\r\n            print \'Error!: \' . $e->getMessage() . \'<br/>\';\r\n            die();\r\n        }\r\n    }\r\n}\r\n','2026-10-15 14:38:04'),
(5,'6788ff5f-7663-4da8-b141-1cf3022b2e9a','index.php','<?php\r\n$active = \'Campus List\';\r\nsession_start();\r\ninclude_once \'../../app/classes/Database.class.php\';\r\ninclude_once \'../../app/classes/Page.class.php\';\r\ninclude_once \'../../app/classes/models/Extras.php\';\r\n\r\nif (!isset($_SESSION[\'user_name\'])) {\r\n    Page::route(\'/login.php\');\r\n}\r\n\r\ninclude_once \'../../app/resources/views/start.layout.php\';\r\ninclude_once \'../../app/resources/views/components/datatable-link.component.php\';\r\ninclude_once \'../../app/resources/views/header.layout.php\';\r\n?>\r\n<div class=\"content-wrapper\">\r\n    <div class=\"page-toolbar\">\r\n        <div class=\"page-toolbar-end\">\r\n            <a href=\"#\" role=\"button\" tag=\"add-campus\" class=\"btn btn-primary\" data-toggle=\"modal\" data-target=\"#campus-modal\"><i class=\"fas fa-plus\"></i> Add Campus</a>\r\n        </div>\r\n    </div>\r\n    <div class=\"content bg-white p-3\">\r\n        <table class=\"table table-hover table-list\" id=\"table-campus\">\r\n            <thead>\r\n                <tr>\r\n                    <th>Code</th>\r\n                    <th>Description</th>\r\n                    <th class=\"col-actions\">Action</th>\r\n                </tr>\r\n            </thead>\r\n        </table>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"modal fade\" id=\"campus-modal\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"campus-modal-title\" aria-hidden=\"true\">\r\n    <div class=\"modal-dialog\" role=\"document\">\r\n        <div class=\"modal-content\">\r\n            <div class=\"modal-header\">\r\n                <h5 class=\"modal-title\" id=\"campus-modal-title\">Campus</h5>\r\n                <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-label=\"Close\">\r\n                    <span aria-hidden=\"true\">&times;</span>\r\n                </button>\r\n            </div>\r\n            <div class=\"modal-body\">\r\n                <div tag=\"display\">\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script src=\"<?php echo Page::asset(\'/public/plugins/bs-stepper/js/bs-stepper.min.js\'); ?>\"></script>\r\n<script src=\"<?php echo Page::asset(\'/public/plugins/jquery-ui/jquery-ui.js\'); ?>\"></script>\r\n<script src=\"<?php echo Page::asset(\'/public/plugins/toastr/toastr.min.js\'); ?>\"></script>\r\n\r\n<?php include_once \'../../app/resources/views/footer.layout.php\'; ?>\r\n<?php include_once \'../../app/resources/views/components/required-script.component.php\'; ?>\r\n<?php include_once \'../../app/resources/views/components/datatable-script.component.php\'; ?>\r\n<script>\r\n    $(function() {\r\n        $(\"#table-campus\").DataTable({\r\n            ajax: {\r\n                method: \'POST\',\r\n                url: \"../../app/includes/getCampusList.inc.php\",\r\n            },\r\n            columns: [\r\n                {\r\n                    data: 1\r\n                }, {\r\n                    data: 2\r\n                }, {\r\n                    data: 0,\r\n                    className: \'col-actions\',\r\n                    orderable: false,\r\n                    render: function(data) {\r\n                        return `<div class=\"table-actions\"><a href=\"#\" role=\"button\" id=\"${data}\" tag=\"edit-campus\" class=\"btn btn-sm btn-icon btn-secondary\" data-toggle=\"modal\" data-target=\"#campus-modal\" aria-label=\"Edit\" title=\"Edit\"><i class=\"fas fa-pen\" aria-hidden=\"true\"></i></a><a href=\"#\" role=\"button\" id=\"${data}\" tag=\"delete-campus\" class=\"btn btn-sm btn-icon btn-outline-danger\" aria-label=\"Delete\" title=\"Delete\"><i class=\"fas fa-trash\" aria-hidden=\"true\"></i></a></div>`\r\n                    }\r\n                }\r\n            ],\r\n        });\r\n\r\n        // Shared dialog helpers: set the title and clear stale content while loading.\r\n        function openDialog(title) {\r\n            $(\'#campus-modal-title\').text(title);\r\n            $(\"div[tag=display]\").html(\'<div class=\"modal-loading\" role=\"status\"><i class=\"fas fa-spinner fa-spin\" aria-hidden=\"true\"></i> Loading…</div>\');\r\n        }\r\n\r\n        $(\"a[tag=add-campus]\").on(\'click\', function() {\r\n            openDialog(\'Add campus\');\r\n            $.ajax({\r\n                url: \'campus_details.php?\',\r\n                success: function(data) {\r\n                    $(\"div[tag=display]\").html(data);\r\n                }\r\n            })\r\n        });\r\n\r\n        $(\"#table-campus\").on(\'click\', \'a[tag=edit-campus]\', function() {\r\n            var id = $(this).attr(\'id\');\r\n            openDialog(\'Edit campus\');\r\n            $.ajax({\r\n                url: \'campus_details.php?id=\' + id,\r\n                success: function(data) {\r\n                    $(\"div[tag=display]\").html(data);\r\n                }\r\n            })\r\n        });\r\n        \r\n        $(\"#table-campus\").on(\'click\', \'a[tag=delete-campus]\', function() {\r\n            var id = $(this).attr(\'id\');\r\n            toastrConfirm(\"Once deleted, you will not be able to recover this campus!\", function () {\r\n                $.ajax({\r\n                    url: \'<?=Extras::fileExists(\"app/classes/controllers/CampusController.class.php\");?>?action=deleteCampus\',\r\n                    type: \'POST\',\r\n                    data: { id: id },\r\n                    success: function (response) {\r\n                        var res = JSON.parse(response);\r\n                        if (res.status === \'success\') {\r\n                            toastr.success(res.message);\r\n                            $(\'#table-campus\').DataTable().ajax.reload();\r\n                        } else {\r\n                            toastr.error(res.message);\r\n                        }\r\n                    },\r\n                    error: function() {\r\n                        toastr.error(\'Something went wrong. Please try again.\');\r\n                    }\r\n                });\r\n            });\r\n        });\r\n        \r\n        function toastrConfirm(message, onConfirm) {\r\n            opsConfirm({\r\n                title: \'Delete this campus?\',\r\n                message: message,\r\n                confirmText: \'Delete\',\r\n                tone: \'danger\'\r\n            }).then(function (confirmed) {\r\n                if (confirmed && typeof onConfirm === \'function\') onConfirm();\r\n            });\r\n        }\r\n    });\r\n</script>\r\n<script src=\"../../public/assets/js/ajax.min.js\"></script>\r\n<script src=\"../../public/assets/js/sweetalert.min.js\"></script>\r\n<?php include_once \'../../app/resources/views/end.layout.php\'; ?>\r\n','2026-10-15 14:38:04');
